import { test } from 'node:test';
import assert from 'node:assert/strict';
import { slugify, slugifyUnique } from '../slug.js';
test('basic', () => assert.equal(slugify('  Hello, World!  '), 'hello-world'));
test('accents', () => assert.equal(slugify('Café Crème Brûlée'), 'cafe-creme-brulee'));
test('runs collapse', () => assert.equal(slugify('a -- b __ c'), 'a-b-c'));
test('empty', () => assert.equal(slugify('!!!'), ''));
test('unique', () => {
  const taken = new Set(['post', 'post-2']);
  assert.equal(slugifyUnique('Post', taken), 'post-3');
  assert.equal(slugifyUnique('New', taken), 'new');
});

